// Two new chapters per character. Options are [id, player line, NPC response].
// Finish options are [id, player line, NPC closing line, recorded outcome].
export const personalFollowups={
 'taei:2':{person:'taei',episode:2,previous:'taei',title:'같은 결말, 다른 이야기',places:['library','cafe','arts'],intro:'지난번 작업 메모 옆에 읽던 작품의 마지막 장면을 적는다. 누군가는 해피엔딩이라고 했지만, 태이에게는 끝내 말하지 못한 인사가 먼저 남았다.',opening:'내가 좋았던 장면하고, 사람들이 좋아한 이유가 꼭 같지는 않네.',options:[['image','결말에서 오래 남은 이미지 하나를 골라 가사로 옮긴다.','사건을 요약하는 대신, 돌아서는 뒷모습과 비어 있는 자리의 느낌을 적었다. 설명을 줄이자 오히려 내가 읽은 결말에 가까워졌다.'],['opposite','내 해석과 반대되는 인물의 입장에서 짧게 써본다.','처음에는 이해하지 못했던 선택에도 그 인물이 알고 있던 사정이 있었다. 내 해석이 유일한 답은 아니라는 여백을 남겼다.'],['rhythm','같은 문장을 다른 리듬으로 두 번 읽어본다.','서두르면 변명처럼, 멈춰 읽으면 미련처럼 들렸다. 단어를 바꾸기 전에 쉬는 자리를 표시했다.']],second:[['keep','다른 해석도 지우지 않고 작업 노트에 함께 남긴다.','다음에 다시 읽으면 또 다른 걸 볼 수도 있겠지.','처음의 가사 옆에 다른 해석을 남겼다. 정답 대신 나중에 돌아볼 두 가지 시선을 기록했다.'],['humming','마음에 남는 한 구절만 허밍으로 옮긴다.','설명은 덜 했는데, 이쪽이 내가 말하려던 느낌에 가깝다.','장면에서 떠올린 한 구절을 허밍 메모로 남겼다. 이전 작업 노트와 이어 볼 지점도 표시했다.']],callback:'지난번에 남긴 두 가지 해석을 다시 읽어볼 때가 됐다.'},
 'taei:3':{person:'taei',episode:3,previous:'taei:2',title:'끝내는 것도 연습',places:['arts','music','cafe','library'],intro:'고칠 곳을 표시한 데모 메모가 어느새 한 페이지를 넘겼다. 작은 수정만 더 하면 될 것 같은데, 그 작은 수정 때문에 남에게 들려줄 시점이 계속 미뤄진다.',opening:'이걸 완성이라고 부르려면, 어디에서 멈춰야 하지.',options:[['limit','오늘 바꿀 구간을 딱 하나만 정한다.','가장 걸리는 후렴 한 구간만 남기고 나머지는 오늘 건드리지 않기로 했다. 좋아질 가능성과 끝없이 미룰 이유를 구분해봤다.'],['listen','수정하지 않고 처음부터 끝까지 들어본다.','고칠 부분을 찾느라 잊고 있던 곡의 흐름이 들렸다. 처음 적었던 한 줄이 아직 가운데 남아 있었다.'],['story','처음 이 곡으로 하고 싶었던 말을 다시 읽는다.','좋은 소리를 내고 싶었던 건 맞지만, 그보다 먼저 내 이야기를 남기고 싶었다. 처음 메모에서 지금 곡에 없는 문장을 찾았다.']],second:[['version','지금 버전을 날짜와 함께 보관하고 다음 수정은 따로 시작한다.','완성도가 마음에 안 들어도, 오늘 만든 건 남겨두자.','현재 버전을 작업 기록으로 구분했다. 실제 음원 발매를 자동 처리하지 않고 다음에 이어갈 수정 메모를 남겼다.'],['question','누군가에게 들려줄 때 묻고 싶은 질문 하나를 적는다.','잘했는지만 묻기보다, 이야기가 전해졌는지 듣고 싶다.','데모를 아직 공개하지 않고 피드백 질문을 정리했다. 다음에 들려줄 준비와 실제 공개를 구분했다.']],callback:'멈춘 지점을 남겨둔 덕분에, 다음 작업을 처음부터 다시 시작하지 않아도 됐다.'},
 'yeogyeong:2':{person:'yeogyeong',episode:2,previous:'yeogyeong',title:'계획에 없던 간식 시간',places:['hall','cafeteria','cafe','library'],intro:'여경이 작은 과자 봉지를 꺼내더니 태이를 보고 웃는다. “이건 공용 물품 아니고 제가 산 거예요.” 먼저 선을 긋는 말투가 어쩐지 장난스럽다.',opening:'오늘은 계산기 안 켜려고요. 근데 하나씩 세어 먹으면 좀 이상해 보이겠죠?',options:[['taste','맛을 맞히는 작은 놀이를 하자고 한다.','설명 듣고 맞히기예요? 그러면 제가 일부러 어렵게 설명할 수도 있는데.'],['fair','누가 더 먹었는지 세지 말고 편하게 나누자고 웃는다.','아, 그 말은 제가 할 줄 알았는데 먼저 하시네요. 오늘은 진짜 안 셀 거예요.'],['break','과자보다 먼저, 오늘은 무슨 일로 쉬러 왔는지 묻는다.','딱히 큰일이 있어야 쉬는 건 아니잖아요. 저도 그냥 과자 먹고 싶어서 나온 거예요.']],second:[['play','서로 과자 맛을 엉뚱하게 설명하며 잠깐 웃는다.','태이 씨 설명은 맛보다 노래 제목 같아요. 먹어봐도 무슨 말인지 모르겠는데.','정답이나 양을 겨루지 않고 간식을 나누며 쉬었다. 여경의 꼼꼼한 모습과 다른 가벼운 장난을 알게 됐다.'],['quiet','오늘은 일을 꺼내지 않고 편하게 쉬는 시간으로 남긴다.','그럼 오늘 이 시간은 아무 일 안 한 걸로 해요. 기록 안 해도 기억하면 되니까.','새 부탁을 만들지 않고 짧은 휴식을 함께했다. 현장에서 나눈 간식을 개인 소지품으로 추가하지 않았다.']],callback:'그날 과자 설명, 나중에 생각하니까 더 이상하던데요. 아직도 무슨 맛인지 모르겠어요.'},
 'yeogyeong:3':{person:'yeogyeong',episode:3,previous:'yeogyeong:2',title:'이번에는 내가 도와줄게요',places:['hall','library','cafeteria','cafe'],intro:'태이가 작업 메모와 강의 자료를 번갈아 펼치자 여경이 먼저 말을 건다. 무슨 문제인지 듣기도 전에 손을 뻗지는 않고, 옆자리에서 기다린다.',opening:'항상 제 쪽만 같이 봤잖아요. 오늘은 태이 씨가 어디서 막혔는지 들어봐도 돼요?',options:[['accept','지금 헷갈리는 일 하나만 골라 설명하고 도움을 받아본다.','아, 다 해달라는 말은 아니군요. 그럼 제가 들은 순서대로 한번 정리해볼게요.'],['scope','내가 맡을 부분과 함께 봐줬으면 하는 부분을 나눈다.','그렇게 말해 주니까 오히려 편해요. 어디까지 도와야 하는지 모르면 저도 괜히 더 하게 되거든요.'],['refuse','내 일이니 혼자 하면 된다며 바로 거절한다.','혼자 할 수 있는 건 알아요. 할 수 있느냐랑, 같이 하고 싶으냐는 조금 다른 얘기라서요.']],second:[['share','정리한 순서를 받아 적고 서로 맡을 일을 작게 나눈다.','이 정도면 저도 부담 없어요. 다 맡기라는 말은 아니었으니까.','태이는 실제로 받은 도움을 인정하고 남은 일은 직접 정리했다. 여경은 도움을 주고받는 범위를 말로 확인했다.'],['thanks','대신 해결해 달라고 하지 않고 들어준 것에 고맙다고 말한다.','그 정도는 받아도 돼요. 고맙다는 말까지 들으면 저도 괜히 뿌듯하거든요.','문제를 전부 해결했다고 과장하지 않고, 이야기하며 정리된 부분만 남겼다. 태이가 혼자 감당하려는 습관을 돌아봤다.']],callback:'지난번처럼 어디까지 같이 볼지 말해 주면, 다음에도 도와주기 편할 것 같아요.'},
 'seoyeon:2':{person:'seoyeon',episode:2,previous:'seoyeon',title:'뜻밖의 승부욕',places:['hall','cafe','cafeteria','library'],intro:'쉬는 시간, 서연이 태이와 같은 쪽으로 종이를 집으려다 손을 거둔다. “가위바위보 할까요?” 차분하게 제안했는데 시선은 생각보다 진지하다.',opening:'진 사람이 테이블 정리하기요. 돈 거는 건 말고요. 한 번만 해요.',game:'rps',options:[['rock','주먹을 낸다.',''],['paper','보를 낸다.',''],['scissors','가위를 낸다.','']],second:[['honor','승패를 받아들이고 테이블을 함께 정리한다.','같이 하면 내기한 의미가 없는데요. 그래도 저는 이쪽 치울게요.','작은 승부 뒤 테이블의 각자 물건을 정리했다. 승패로 호감도를 더 주지 않고 서연의 의외로 진지한 면을 보았다.'],['rematch','다음에 한 번 더 하자고 하고 오늘은 여기서 마친다.','기억해둘게요. 다음에 제가 먼저 얘기해도 모른 척하기 없어요.','즉시 재대결을 강요하지 않고 다음의 작은 장난거리로 남겼다. 실제 약속 시각을 자동으로 잡지는 않았다.']],callback:'가위바위보 한 번 더 하자고 한 거, 그냥 한 말은 아니었죠?'},
 'seoyeon:3':{person:'seoyeon',episode:3,previous:'seoyeon:2',title:'말하지 않아도 아는 사이?',places:['hall','library','cafe','cafeteria'],intro:'서연은 평소처럼 웃다가 휴대폰을 잠시 뒤집어 둔다. 태이가 눈치를 살피자 먼저 고개를 젓는다. “무슨 생각인지 맞히려고 하진 말고요.”',opening:'눈치가 빠른 건 좋은데, 제가 말하기 전에 결론까지 나 있으면 조금 서운할 때도 있어요.',options:[['ask','내가 짐작한 건 잠시 접고 지금 원하는 걸 직접 묻는다.','오늘은 그냥 잠깐 조용히 있고 싶었어요. 기분 나쁜 건 아니고요. 이렇게 물어보면 대답할 수 있잖아요.'],['admit','눈치를 보다가 너무 빨리 단정할 때가 있다고 인정한다.','저도 괜찮다고 먼저 말해버릴 때가 있으니까요. 둘 다 말 안 해도 통한다고 생각하면 더 헷갈리겠네요.'],['assume','표정만 봐도 알 것 같다고 다시 확신한다.','제가 아니라고 말할 자리도 남겨주면 좋겠어요. 알아주는 것하고 정해 주는 건 다르니까.']],second:[['signal','혼자 있고 싶을 때와 같이 있고 싶을 때 편하게 말하기로 한다.','대단한 암호 같은 건 말고요. 오늘은 조용히 있고 싶다, 그 정도면 충분해요.','서로의 마음을 읽는 대신 간단한 말로 확인하기로 했다. 태이의 빠른 눈치가 늘 정답은 아니라는 여지를 남겼다.'],['space','지금은 조용히 쉬고, 나도 필요한 게 있으면 말하겠다고 한다.','좋아요. 오늘은 이대로 조금만 쉬어요. 뭘 계속 해줘야 하는 건 아니니까.','침묵을 불만이나 거절로 단정하지 않고 잠깐 함께 쉬었다. 각자의 편안한 거리를 확인했다.']],callback:'지난번에 말한 것처럼요. 오늘은 제가 먼저 필요한 걸 얘기해 볼게요.'},
 'soyul:2':{person:'soyul',episode:2,previous:'soyul',title:'렌즈 밖으로 한 걸음',places:['library','hall','cafe'],intro:'창가의 빛을 보던 소율이 휴대폰을 들었다가 내린다. “혹시 여기 잠깐 서 있어 주실 수 있어요?” 부탁한 뒤에야 시선을 마주친다.',opening:'모델처럼 해달라는 건 아니고요. 사람이 있으면 구도가 어떻게 달라지는지 보고 싶어서.',options:[['natural','편한 자세로 서고 어느 쪽을 보면 되는지 묻는다.','그냥 창밖 봐주시면… 네, 그렇게요. 아, 너무 가만히 계실 필요는 없어요.'],['pose','일부러 과장된 포즈를 취하고 가볍게 웃는다.','아니, 그런 거 말고… 잠깐, 지금 건 좀 웃긴데. 그 표정 한 번만 더요.'],['frame','얼굴이 나오지 않는 뒷모습이나 손부터 찍어보자고 한다.','그것도 좋아요. 얼굴이 꼭 보여야 사람의 느낌이 나는 건 아니니까.']],second:[['review','찍힌 사진을 함께 보고 남길 범위를 서로 확인한다.','태이 씨가 불편한 건 지울게요. 찍게 해줬다고 다 괜찮다는 뜻은 아닐 테니까.','촬영과 보관의 범위를 함께 확인했다. 동의하지 않은 사진을 임의로 저장·전송하지 않았다.'],['delete','연습한 구도만 기억하고 사진은 지금 지우자고 한다.','알겠어요. 그래도 찍는 동안 어떤 느낌인지는 봤으니까요. 도와줘서 고마워요.','구도를 연습한 뒤 촬영 파일은 지운 것으로 정리했다. 삭제 선택 때문에 관계를 자동으로 나쁘게 만들지 않았다.']],callback:'지난번에 서 계셨던 구도, 사람 없이 다시 보니까 느낌이 진짜 다르더라고요.'},
 'soyul:3':{person:'soyul',episode:3,previous:'soyul:2',title:'지우지 않은 한 줄',places:['library','cafe','hall'],intro:'소율이 사진 아래 적어 둔 짧은 글을 보여준다. 보여주기 직전까지도 마지막 단어를 고치다가, 이번에는 화면을 끄지 않는다.',opening:'사진 설명은 아닌데… 적어놓고 보니까 그냥 제 얘기 같아서요. 어색해도 끝까지 한 번 읽어주실래요?',options:[['read','평가부터 하지 않고 끝까지 읽은 다음 어떤 반응을 원하는지 묻는다.','잘 썼다는 말보다, 무슨 말인지 전해졌는지가 궁금했어요. 제가 너무 혼자만 아는 얘기를 쓴 건가 해서.'],['share','나도 다듬다 만 문장을 꺼내 서로 읽어본다.','이건 아직 안 끝낸 거예요? 저도 완성 안 된 걸 보여드린 거니까… 그럼 좀 덜 민망하네요.'],['fix','읽는 도중 어색한 표현부터 바로 고쳐준다.','고칠 곳이 있다는 건 아는데, 먼저 끝까지 읽어주셨으면 했어요. 그다음에 물어보려고요.']],second:[['interpret','내가 읽은 뜻을 말하고 본인이 쓰려던 뜻과 비교해본다.','다르게 읽힐 수도 있네요. 그게 꼭 틀린 건 아닌데, 제가 더 남기고 싶은 부분은 알 것 같아요.','태이의 해석을 정답으로 두지 않고 소율이 남기고 싶은 뜻을 확인했다. 수정 여부는 소율이 결정했다.'],['unfinished','미완성으로 남겨도 된다며 오늘은 여기까지만 읽는다.','그럼 오늘은 안 지울게요. 나중에 다시 보면 지금보다 덜 어색할지도 모르니까.','글을 서둘러 공개하거나 완성시키지 않았다. 소율이 자기 문장을 남겨 두기로 한 선택을 함께 기억했다.']],callback:'그때 읽어드린 글, 아직 남겨뒀어요. 마지막 단어는 또 바뀌었지만요.'},
 'iseo:2':{person:'iseo',episode:2,previous:'iseo',title:'승부는 한 번만',places:['gym','field','outdoorCourt'],intro:'운동을 마친 이서가 바닥의 선 옆에 선다. 이번에는 무작정 기록부터 재지 않고 태이 쪽을 보며 웃는다.',opening:'한 발로 균형 잡기 어때요? 무리하기 없기. 넘어질 것 같으면 그냥 내려놓는 걸로요.',game:'balance',options:[['steady','호흡을 맞추고 안정적으로 버틴다.','기록도 안 쟀는데 왜 이렇게 진지해요? 아, 저도 말하다가 흔들렸네.'],['rhythm','숫자 대신 짧은 리듬을 맞추며 버틴다.','이러면 운동보다 합주 같은데요. 근데 리듬 맞추니까 덜 긴장돼요.'],['playful','무리하지 않는 선에서 서로 웃음을 참아본다.','저 웃기면 안 되죠. 아니, 제가 먼저 웃었나? 잠깐만 다시… 아, 한 번만 하기로 했지.']],second:[['finish','결과보다 자세를 정리하고 약속한 한 번에서 끝낸다.','끝내자고 먼저 말해주니까 좋네요. 저 혼자였으면 한 번 더 했을 것 같아서.','짧은 균형 놀이 후 발목을 풀고 마쳤다. 이기기 위해 몸을 무리하게 쓰는 선택이나 돈 내기는 하지 않았다.'],['laugh','잘 버틴 쪽을 인정하고 가볍게 장난치며 마친다.','인정은 해요. 근데 오늘 진 걸로 다음에도 무조건 질 거라고 생각하면 안 돼요.','서로의 움직임을 보며 웃고 승부는 그 자리에서 마쳤다. 승패 자체로 추가 호감 보상을 주지 않았다.']],callback:'한 번만 하고 끝내자고 했던 거요. 혼자 운동할 때도 한번 써봤어요.'},
 'iseo:3':{person:'iseo',episode:3,previous:'iseo:2',title:'오늘은 듣는 쪽',places:['gym','field','outdoorCourt'],intro:'이서는 하려던 말을 멈추고 태이에게 먼저 물병을 챙길 시간을 준다. “맨날 제 운동 얘기만 했네요.” 이번에는 대답을 기다린다.',opening:'오늘은 제가 들어볼게요. 운동 말고 요즘 제일 많이 생각하는 거, 뭐예요?',options:[['music','음악을 통해 내 이야기를 남기고 싶은 마음을 말한다.','노래를 잘하고 싶다는 거랑은 조금 다른 얘기네요. 그러면 듣는 사람한테 뭘 제일 남기고 싶어요?'],['home','목포에 있는 가족과 혼자 사는 생활 이야기를 조금 나눈다.','멀리 있으면 별일 없어도 문득 생각날 때 있죠. 지금 다 얘기 안 해도 돼요. 그냥 들어볼게요.'],['ask','이서는 남의 이야기를 들을 때 어떤지 가볍게 되묻는다.','저 말만 많이 하는 사람은 아니거든요? 아, 지금도 제가 말했네. 그래도 이번엔 진짜 기다릴 수 있어요.']],second:[['thanks','들어줘서 고맙다고 하고, 다음에는 이서의 다른 이야기도 듣기로 한다.','좋아요. 다음에 제가 또 운동 얘기부터 하면 다른 얘기도 하라고 말해줘요.','태이가 말하고 이서가 듣는 시간을 가졌다. 말이 많은 모습 외에 기다려 줄 줄 아는 면을 알게 됐다.'],['exchange','다 말할 필요 없이 서로 편한 만큼 나누자고 한다.','그게 좋겠네요. 가까워지려면 무조건 다 알아야 하는 건 아닐 테니까요.','큰 고백을 강요하지 않고 서로 말할 범위를 정했다. 가까움과 사적인 영역을 함께 남겨 두었다.']],callback:'지난번 얘기, 운동하다가도 문득 생각났어요. 오늘은 어디까지 이야기해볼까요?'}
};
export function followupGameOutcome(def,choice,roll){
 if(def.game==='rps'){const hands=['rock','paper','scissors'],i=hands.indexOf(choice);if(i<0)return null;const result=i===roll?'tie':(i-roll+3)%3===1?'win':'lose';return {result,npcHand:hands[roll],text:result==='tie'?'둘 다 같은 손을 내고 잠깐 멈춘다. 서연이 먼저 웃는다. “이러면 정리도 같이 하는 거죠?”':result==='win'?'서연이 자기 손을 내려다보더니 입술을 한번 다문다. “졌네요. 알겠어요. 다음에는 안 봐줄 거예요.”':'서연은 조용히 손을 거두고 웃는다. “저 이런 건 꽤 진지하게 해요. 테이블은 같이 치워도 되고요.”'};}
 if(def.game==='balance'&&choice!=='introduce')return {result:['taei','iseo','both'][roll],text:['이서가 먼저 발을 내려놓고 웃는다. “오늘은 인정할게요. 대신 무리해서 버티지는 말기요.”','태이가 먼저 발을 내리자 이서가 반갑게 웃는다. “저도 잘하는 거 있거든요. 다음에도 그냥 이기게 해주진 마세요.”','둘이 거의 동시에 발을 내리고 마주 웃는다. 기록보다 웃음을 참는 쪽이 어려웠다.'][roll]};
 return null;
}
